import{filterRows,summaries,totals}from'./core.js';
const labels={all:'Tổng hợp tất cả trạng thái',done:'Đã làm',passed:'Đã làm – Đạt',failed:'Đã làm – Chưa đạt',absent:'Chưa làm',error:'Bị lỗi'};
const statusNames={passed:'Đạt',failed:'Chưa đạt',absent:'Chưa làm',error:'Bị lỗi'};
export function contestReportData(title,allRows,filters={}){
  const scope=filterRows(allRows,{years:filters.years,branch:filters.branch});
  const rows=filterRows(allRows,filters),t=totals(scope);
  const years=filters.years?.length?[...filters.years].sort().reverse():['2026','2025','2024','2023'];
  const range='Phạm vi: Khóa '+years.join(', ')+(filters.branch?' · Chi đoàn '+filters.branch:'');
  const filter='Bộ lọc: '+(labels[filters.status]||labels.all)+(filters.q?' · Tìm kiếm: '+filters.q:'');
  return {title,range,filter,totals:t,rows:rows.map((r,i)=>[i+1,r.name,r.ids.join(', '),r.dob||'',r.gender||'',Number(r.year)||r.year,r.branch,statusNames[r.status],r.result?.score??'',r.result?.submitted??'',r.error?.reason||'']),summary:summaries(scope).map((s,i)=>[i+1,s.branch,s.total,s.passed,s.failed,s.absent,s.error,s.total?s.done/s.total:0])};
}
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c])).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'');
const col=i=>{let s='';for(i++;i;i=Math.floor((i-1)/26))s=String.fromCharCode(65+(i-1)%26)+s;return s;};
export async function exportContestReport(title,allRows,filters={},now=new Date()){
  const report=contestReportData(title,allRows,filters),t=report.totals;
  const parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now).map(p=>[p.type,p.value]));
  const stamp=`Thời gian xuất file: ${parts.hour}:${parts.minute} ${parts.day}/${parts.month}/${parts.year}`;
  const detailHeaders=['STT','Họ và tên','Mã định danh','Ngày sinh','Giới tính','Khóa','Chi đoàn','Trạng thái','Điểm','Thời gian nộp bài','Ghi chú'];
  const summaryHeaders=['STT','Chi đoàn','Sĩ số','Đạt','Chưa đạt','Chưa làm','Bị lỗi','Tỷ lệ đã làm'];
  const summary=[...report.summary,['','TỔNG',t.total,t.passed,t.failed,t.absent,t.error,t.total?t.done/t.total:0]];
  const count=`Số lượng đoàn viên trong danh sách: ${report.rows.length}  |  Tổng đoàn viên phạm vi: ${t.total} (Đạt ${t.passed} · Chưa đạt ${t.failed} · Chưa làm ${t.absent} · Bị lỗi ${t.error})`;
  function sheet(headers,rows,meta,widths,summary=false){
    const end=col(headers.length-1),headerRow=meta.length+2,first=headerRow+1;
    const cell=(v,c,r,style)=>typeof v==='number'&&Number.isFinite(v)?`<c r="${col(c)}${r}" s="${style}"><v>${v}</v></c>`:`<c r="${col(c)}${r}" s="${style}" t="inlineStr"><is><t xml:space="preserve">${escape(v)}</t></is></c>`;
    const data=meta.map((v,i)=>`<row r="${i+1}" ht="${i===0?30:i===meta.length-1&&!summary?34:20}" customHeight="1">${cell(v,0,i+1,i===0?1:(summary?i===1||i===3:i===1||i===2||i===4)?2:3)}</row>`).join('')+`<row r="${headerRow}" ht="34" customHeight="1">${headers.map((h,c)=>cell(h,c,headerRow,4)).join('')}</row>`+rows.map((row,i)=>`<row r="${first+i}" ht="26" customHeight="1">${row.map((v,c)=>{const total=summary&&i===rows.length-1;return cell(v,c,first+i,summary&&c===7?(total?9:8):total?7:(c===1||(!summary&&(c===7||c===10)))?6:5);}).join('')}</row>`).join('');
    return`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><dimension ref="A1:${end}${headerRow+rows.length}"/><sheetViews><sheetView workbookViewId="0"><pane ySplit="${headerRow}" topLeftCell="A${first}" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>${widths.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('')}</cols><sheetData>${data}</sheetData><autoFilter ref="A${headerRow}:${end}${summary?Math.max(headerRow,headerRow+rows.length-1):headerRow+rows.length}"/><mergeCells count="${meta.length}">${meta.map((_,i)=>`<mergeCell ref="A${i+1}:${end}${i+1}"/>`).join('')}</mergeCells><printOptions horizontalCentered="1"/><pageMargins left="0.3" right="0.3" top="0.4" bottom="0.4" header="0.2" footer="0.2"/><pageSetup orientation="landscape" paperSize="9" fitToWidth="1" fitToHeight="0"/></worksheet>`;
  }
  const sheets=[{name:'Danh sách',header:7,xml:sheet(detailHeaders,report.rows,['THỐNG KÊ CUỘC THI: '+title,report.range,report.filter,stamp,count],[6,28,14,13,10,8,15,22,10,18,24])},{name:'Tổng hợp theo chi đoàn',header:6,xml:sheet(summaryHeaders,summary,['TỔNG HỢP THEO CHI ĐOÀN – '+title,report.range,stamp,'Số lượng đoàn viên: '+t.total],[7,18,10,10,10,10,10,14],true)}];
  const z=new JSZip();
  z.file('[Content_Types].xml',`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`);
  z.file('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
  z.file('xl/workbook.xml',`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map((s,i)=>`<sheet name="${s.name}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets><definedNames>${sheets.map((s,i)=>`<definedName name="_xlnm.Print_Titles" localSheetId="${i}">'${s.name}'!$1:$${s.header}</definedName>`).join('')}</definedNames></workbook>`);
  z.file('xl/_rels/workbook.xml.rels',`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="styles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`);
  const xf=(font,border,align,fill=0,format=0)=>`<xf fontId="${font}" fillId="${fill}" borderId="${border}" numFmtId="${format}" xfId="0" applyAlignment="1"${format?' applyNumberFormat="1"':''}><alignment horizontal="${align}" vertical="center" wrapText="1"/></xf>`;
  z.file('xl/styles.xml',`<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="1"><numFmt numFmtId="164" formatCode="0.0%"/></numFmts><fonts count="3"><font><sz val="12"/><name val="Times New Roman"/></font><font><b/><sz val="15"/><name val="Times New Roman"/></font><font><b/><sz val="12"/><name val="Times New Roman"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFE7ECF5"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="2"><border/><border><left style="thin"><color rgb="FF000000"/></left><right style="thin"><color rgb="FF000000"/></right><top style="thin"><color rgb="FF000000"/></top><bottom style="thin"><color rgb="FF000000"/></bottom></border></borders><cellStyleXfs count="1"><xf fontId="0" fillId="0" borderId="0" numFmtId="0"/></cellStyleXfs><cellXfs count="10">${xf(0,0,'center')+xf(1,0,'center')+xf(2,0,'center')+xf(0,0,'center')+xf(2,1,'center',2)+xf(0,1,'center')+xf(0,1,'left')+xf(2,1,'center')+xf(0,1,'center',0,164)+xf(2,1,'center',0,164)}</cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`);
  sheets.forEach((s,i)=>z.file(`xl/worksheets/sheet${i+1}.xml`,s.xml));
  return z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
}
